/**
 * Architecture Contract: Event System
 *
 * These tests codify the public interface of events/types.js and events/dispatch.js.
 * If a refactoring breaks these tests, the interface has changed —
 * that's a breaking change, not a refactoring.
 *
 * Generated by /architect
 */

const events = require('../../src/events/types');
const { registerSink, removeSink, clearSinks, dispatch, sinkCount } = require('../../src/events/dispatch');
const { createArchitectureCaptureSink } = require('./sinks/architecture-capture');

describe('Event types interface contract', () => {
  test('event() creates a timestamped object with the given type', () => {
    const e = events.event('test.type', { foo: 'bar' });
    expect(e.type).toBe('test.type');
    expect(e.timestamp).toBeInstanceOf(Date);
    expect(e.foo).toBe('bar');
  });

  test('all 23 domain event constructors are exported', () => {
    const expectedExports = [
      'event',
      'tokenReserved', 'tokenMinted', 'tokenListed', 'tokenDelisted',
      'tokenDelistedAll', 'tokenSold', 'licenseGranted',
      'licenseCreated',
      'watermarkApplied', 'watermarkProgress',
      'ipfsUploaded', 'ipfsCacheHit', 'ipfsUnpinned',
      'arweaveUploaded',
      'watermarkDetected',
      'aiGenerated', 'aiCleanup',
      'mintStarted', 'mintStep', 'mintCompleted', 'mintFailed',
      'detectStarted', 'detectCompleted', 'detectFailed',
    ];

    for (const name of expectedExports) {
      expect(typeof events[name]).toBe('function');
    }
  });

  test('token lifecycle events have correct type strings', () => {
    expect(events.tokenReserved({ tokenId: 1, expiry: 0, transactionHash: '0x' }).type).toBe('token.reserved');
    expect(events.tokenMinted({ tokenId: 1, to: '0x', transactionHash: '0x', blockNumber: 1, imageHash: '0x', ipfsUri: '', uri: '', licenseType: 0 }).type).toBe('token.minted');
    expect(events.tokenListed({ tokenId: 1, price: '1', licenseType: 0, transactionHash: '0x' }).type).toBe('token.listed');
    expect(events.tokenDelisted({ tokenId: 1, licenseType: 0 }).type).toBe('token.delisted');
    expect(events.tokenDelistedAll({ tokenId: 1 }).type).toBe('token.delisted_all');
    expect(events.tokenSold({ tokenId: 1, seller: '0x', buyer: '0x', price: '1', licenseType: 0 }).type).toBe('token.sold');
    expect(events.licenseGranted({ newTokenId: 2, parentTokenId: 1, buyer: '0x', licenseType: 0 }).type).toBe('license.granted');
  });

  test('mock flag defaults to false when omitted', () => {
    const e = events.tokenReserved({ tokenId: 1, expiry: 0, transactionHash: '0x' });
    expect(e.mock).toBe(false);
  });

  test('mock flag is preserved when explicitly set', () => {
    const e = events.tokenReserved({ tokenId: 1, expiry: 0, transactionHash: '0x', mock: true });
    expect(e.mock).toBe(true);
  });

  test('events are plain objects (not class instances)', () => {
    const e = events.mintStarted({ mintId: 'abc', wallet: '0x' });
    expect(Object.getPrototypeOf(e)).toBe(Object.prototype);
  });
});

describe('Event dispatch interface contract', () => {
  let capture;

  beforeEach(() => {
    clearSinks();
    capture = createArchitectureCaptureSink('dispatch-contract');
  });

  afterEach(() => {
    clearSinks();
  });

  test('starts with zero sinks', () => {
    expect(sinkCount()).toBe(0);
  });

  test('registerSink adds a sink, removeSink removes it', () => {
    registerSink(capture.sink);
    expect(sinkCount()).toBe(1);

    removeSink(capture.sink);
    expect(sinkCount()).toBe(0);
  });

  test('clearSinks removes all sinks', () => {
    registerSink(capture.sink);
    registerSink(() => {});
    expect(sinkCount()).toBe(2);

    clearSinks();
    expect(sinkCount()).toBe(0);
  });

  test('dispatch fans events to all registered sinks', async () => {
    const captured2 = [];
    registerSink(capture.sink);
    registerSink((e) => captured2.push(e));

    const testEvents = [
      events.mintStarted({ mintId: 'x', wallet: '0x' }),
      events.mintCompleted({ mintId: 'x', tokenId: 1, transactionHash: '0x' }),
    ];

    await dispatch(testEvents);

    expect(capture.captured).toHaveLength(2);
    expect(captured2).toHaveLength(2);
    expect(capture.captured[0].type).toBe('mint.started');
    expect(capture.captured[1].type).toBe('mint.completed');
  });

  test('dispatch with empty array is a no-op', async () => {
    registerSink(capture.sink);
    await dispatch([]);
    expect(capture.captured).toHaveLength(0);
  });

  test('a failing sink does not break dispatch to other sinks', async () => {
    const failingSink = () => { throw new Error('boom'); };
    registerSink(failingSink);
    registerSink(capture.sink);

    await dispatch([events.mintStarted({ mintId: 'y', wallet: '0x' })]);

    // capture sink still received the event despite the failing sink
    expect(capture.captured).toHaveLength(1);
  });

  test('removeSink for an unregistered sink is a no-op', () => {
    const unrelated = () => {};
    removeSink(unrelated); // should not throw
    expect(sinkCount()).toBe(0);
  });
});
